                    raise ctypes.WinError(ctypes.get_last_error())
            except BaseException as exc:
                close_failed = True
                cleanup['errors'].append(error_text(exc))
                record_error(exc)
        if nul is not None:
            try:
                nul.close()
            except BaseException as exc:
                close_failed = True
                cleanup['errors'].append(error_text(exc))
                record_error(exc)
        cleanup['handles_closed'] = not close_failed
        result['elapsed_seconds'] = time.monotonic() - started
    return result
